  "AuditionLineA": "Greetings,",
  "AuditionLineB": "I'd like to visit the temple again.",
  "AuditionLineC": ". You will be faced with many challenges throughout your lifetime, and the most difficult\n of these will be dealing with your fellow man. There will come a time when diplomacy and tact\n will prove to be useless and your hand must be raised instead. This challenge prepares you to face\n another human, look him in the eyes, and know that you may have to kill him.",
