  "AuditionLineB": "Just sell me some stimpaks.",
  "AuditionLineC": "Then, I came back here and watched Marcus build the town from the shanties I remember from my\n youth into the \"sprawling metropolis\" you see before you. I saw people attracted by promises of\n wealth. I saw people grow up and die. I saw the currents of history.",
  "Notes": "untagged, vanilla RPU baseline text",
