  "Prefix": "mrcus",
  "Location": "Broken Hills",
  "Mod": "FO2",
  "Status": "Not started",
  "CastStatus": "Not cast",
  "VoiceActor": "",
  "VoiceType": "",
  "THAudio": "",
  "FloatAudio": "",
  "AuditionLineA": "Well, what the hell. I haven't seen one of those outfits for a long, long time. Takes me back.",
  "AuditionLineB": "Humph. Something wasn't right.",
  "AuditionLineC": "Heh. I can use just about any big gun, like rocket launchers or miniguns,\n and the big energy weapons. I ain't bad with my fists, and I'm a hell of a shot with grenades. I don't\n wear armor. They just don't make it my size.",
  "Notes": "untagged, vanilla RPU baseline text",
  "WikiLink": "https://fallout.fandom.com/wiki/Marcus",
  "ImageFile": "",
  "InVockScope": "Yes",
  "THATVoiceActor": "",
