  "FloatAudio": "",
  "AuditionLineA": "Hi! Nice weather we've been having, huh?",
  "AuditionLineB": "Thanks. I'll try that out. Bye!",
  "AuditionLineC": "Oh, yes, the Professor. He grew me from a tiny spore and nurtured me... but I realized from an early age that if I were to act as smart as I truly\n am, he'd cut me into pieces to examine me. So, I played dumb and got planted out here. It's nice... but I'd like to branch out a little.\n Y'know, maybe get planted someplace else...",
  "Notes": "untagged, vanilla RPU baseline text",
