  "AuditionLineB": "Tell me about the place.",
  "AuditionLineC": "We're a small mining community. We were founded several decades ago by our sheriff, Marcus, and\n a man named Jacob. The two of them chose this site because it was near some uranium deposits. Would\n you like to hear more?",
