  "AuditionLineB": "Well, I had a few questions about hunting geckos.",
  "AuditionLineC": "Well, I guess they don't like to crawl through the goo too much. I can't say as I blame them.\n It sure burns if gets on your skin. But that doesn't seem to stop 'em from licking up the darn stuff\n like it was Buckner's Best.",
