  "AuditionLineA": "You bad. You hurt Torr. Go away now!",
  "AuditionLineB": "Torr see bugmen hurt moo-moo.",
  "AuditionLineC": "Ook! Ugmen, Ulik ribal, Smiley mook. (Well, there's my bugmen problem. Then there's Sulik, the tribal, that my mom is making work off a debt \u2014 I think sis is in love with him. Mom's boyfriend, a fellow named Smiley, is missing someplace out to the west. Quite exciting here, lately.)",
