  "VoiceActor": "",
  "VoiceType": "",
  "THAudio": "",
  "FloatAudio": "",
  "AuditionLineA": "My son was mistakenly killed in the fight.",
  "AuditionLineB": ". Now that we're properly introduced, you seem troubled.",
  "AuditionLineC": "Does that mean you'll help me? Thank you! Jonny was last seen playing cowboys and Indians with\n his dog Laddie out front. The two of them are inseparable; in fact, that's how we knew something was\n wrong. One day, Laddie came back without Jonny. We've been searching ever since. Take Laddie with\n you; maybe the two of you will be able to find Jonny.",
  "Notes": "untagged, vanilla RPU baseline text",
  "WikiLink": "https://fallout.fandom.com/wiki/Balthas",
  "ImageFile": "",
  "InVockScope": "Yes",
