  "AuditionLineA": "Other than the slightly unsettled look on his face, there appears to be nothing out of the\n ordinary about him.",
  "AuditionLineB": "I have a watch. It was a gold watch. I wonder where I put it?",
  "AuditionLineC": "A while back, I forget when... my best friend of 30... or was it 40 years? Oh, it doesn't matter,\n what matters is that he stole my precious gold pocket watch. It has been handed down in my family for\n five, no six, err... four generations. Yep, I distinctly remember setting it down on my desk. Then,\n when I looked on the kitchen table, it was gone.",
