  "CastStatus": "Not cast",
  "VoiceActor": "",
  "VoiceType": "",
  "THAudio": "",
  "FloatAudio": "",
  "AuditionLineA": "Hello, I'm Ariel. I don't think I've seen you here before. Who are you?",
  "AuditionLineB": "Tough break. I'll be seeing ya.",
  "AuditionLineC": "I was holding Sandy behind me, trying to keep her from the monster that had shot Rand. He stood\n next to my husband's body and laughed at me as he aimed his gun at my head. Suddenly, this huge claw\n came out of the darkness, grabbed him from behind and... well, thank goodness that Sandy didn't see\n what happened next. Anyway, the raiders were being wiped out by this group of deathclaws. The one that\n saved Sandy and me stood near us and talked to me. He kept reassuring me that I was safe, and that he\n was sorry that he couldn't have gotten there sooner to help us. Afterwards, the deathclaws brought us\n here.",
  "Notes": "untagged, vanilla RPU baseline text",
  "WikiLink": "https://fallout.fandom.com/wiki/Ariel",
