  "Status": "Not started",
  "CastStatus": "Not cast",
  "VoiceActor": "",
  "VoiceType": "",
  "THAudio": "",
  "FloatAudio": "",
  "AuditionLineA": "Well, I'll be. How are you doing,",
  "AuditionLineB": "What do you want to know?",
  "AuditionLineC": "So, I sneak up on this camp site and there are these two deathclaws sitting around the fire just\n chatting away. Idiot that I am, I let out a little cry of surprise, jumped up, and turned to run -- right\n into the arms of another deathclaw standing right behind me. Anyway, to make a long story short, it\n took awhile for me to realize that I wasn't about to be put on a spit and barbecued. Instead, I was\n brought here and 'interviewed' by Gruthar. Now I can live here if I want.",
