  "FloatAudio": "",
  "AuditionLineA": "You're about a taco short of a combination plate.",
  "AuditionLineB": "Interesting. Let me ask you something else, Sheriff Marion.",
  "AuditionLineC": "Didn't I? Must have plum darn slipped my mind. Yup, that's what it did. Well, he's got three\n older brothers... even meaner than he was, from what I hear. Let's see... Toad, Newt and Snake Morton, if\n I remember aright. Heck, you know how tall tales can get. By the way, keep that badge I gave you. You\n earned it... Sheriff. (He smiles.)",
