  "AuditionLineA": "If you had a brain, I think it'd just up and die of loneliness.",
  "AuditionLineB": "Just keep an eye on your own miners too from now on. Goodbye.",
  "AuditionLineC": "Vault City? (he laughs) Those bigots would turn Redding into a slave-labor camp. They don't see\n anyone who's not one of their precious Citizens as being worth a warm bucket of spit. Spending my life\n bowing and scraping to those bigots isn't my idea of any kind of life.",
