  "AuditionLineB": "You cheap bastard! You'll pay for stiffing me. Goodbye.",
  "AuditionLineC": "Hello there. My name's Ben. Ben Wade. I'm in charge of trade caravans between Redding and Vault\n City. I can usually use an extra guard or two. We leave town on the 1st of every month. If you want to\n sign on, make sure you're here then.",
