  "AuditionLineC": "Working with Dave, eh? Yeah, I know the fella. I see he's still got a knack for getting others to do his leg work--lazy bastard.\n [He chuckles.] Anyway, I think I got what you're lookin for, but lemme just go back an' check. [Harry goes into his back room where you\n hear boxes being shuffled and moved around. He returns a minute later.] Yep, got it right here. $500 and she's all yours.",
